def find_kth(arr1, arr2, k, start1, start2):
    # Base case: if one of the arrays or both is empty, return the kth element from the other array
    if start1 >= len(arr1) or start2 >= len(arr2):
        if start1 >= len(arr1):
            return arr2[start2 + k - 1]
        else:
            return arr1[start1 + k - 1]

    # If k equals to 1, return the minimum of the first elements of both arrays
    if k == 1:
        return min(arr1[start1], arr2[start2])

    # Calculate the middle elements of the two arrays
    mid1 = min(start1 + k // 2 - 1, len(arr1) - 1)
    mid2 = min(start2 + k // 2 - 1, len(arr2) - 1)

    # If the middle element of the first array is smaller than the middle element of the second array, 
    # the element we are looking for must be in the second array
    if arr1[mid1] < arr2[mid2]:
        return find_kth(arr1, arr2, k - (mid1 - start1 + 1), mid1 + 1, start2)

    # Otherwise, the element we are looking for must be in the first array
    else:
        return find_kth(arr1, arr2, k - (mid2 - start2 + 1), start1, mid2 + 1)

