    filtered_frequencies = [string for string, freq in frequency.items() if freq > 1]

    # Sort the filtered strings by frequency in descending order
    filtered_frequencies.sort(key=lambda x: frequency[x], reverse=True)

    # Get the second most frequent string if it exists
