    frequency_dict = {}
    for string in string_list:
        if string in frequency_dict:
            frequency_dict[string] += 1
        else:
            frequency_dict[string] = 1

    # Find the maximum frequency
    max_frequency = max(frequency_dict.values())

    # Filter strings with max frequency to find the second most frequent
    second_frequent_set = {string for string, count in frequency_dict.items() if count == max_frequency}

    # Return the second most frequent string
    if len(second_frequent_set) == 1:
        return second_frequent_set.pop()  # Return the only occurrence
    else:
        # Handle edge cases like all elements have the same frequency
        return tuple(second_frequent_set)[1]  # Return the second string in the set
