def max_product(numbers):
    # Edge case: If there are less than 2 numbers, return None or a message
    if len(numbers) < 2:
        return None  # OR "No pair exists"

    # Find the maximum and second maximum numbers in the array
    max1, max2 = 0, 0
    for num in numbers:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

    # Find the minimum and second minimum numbers in the array
    min1, min2 = float('inf'), float('inf')
    for num in numbers:
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Calculate the maximum product of two positive numbers or two negative numbers
    max_product = max(max1 * max2, min1 * min2)
    return (max_product, max1, max2)
