# Define the function calculate_bell_number to compute nth Bell number
def calculate_bell_number(n):
    # Create a list to store bell numbers, initialize the first element
    bell_numbers = [0] * (n+1)
    bell_numbers[0] = 1  # Basis case: Bell number of 0 is 1

    # Loop through each number from 1 to n
    for i in range(1, n+1):
        # Calculate Bell number at index i using the recurrence relation
        bell_numbers[i] = 0
        for j in range(i):
            bell_numbers[i] += bell_numbers[j] * factorial(i-j-1)

    # Return the bell number at the nth position
    return bell_numbers[n]

# Define a helper function factorial to calculate the factorial of a number
def factorial(num):
    # Base case: factorial of 0 is 1
    if num == 0:
        return 1
    # Recursive case: n * factorial of (n-1)
    else:
        return num * factorial(num-1)

