def min_coins(coins, value, n):
    # Base case
    if value == 0:
        return 0
    if n == 0 or value < coins[0]:
        return float('inf')
    # Recursive case with memoization
    dp = [-1000 for _ in range(value+1)]
    dp[0] = 0
    for i in range(1, n+1):
        for j in range(value+1):
            if coins[i-1] <= j:
                dp[j] = min(dp[j], dp[j-coins[i-1]] + 1)
    # Return the result
    return dp[value] if dp[value] != float('inf') else float('inf')
```

