    for i in range(m+1):
        for j in range(n+1):
            if i == 0:
                # If str1 is empty, the only option is to insert all characters of str2
                dp[i][j] = j
            elif j == 0:
                # If str2 is empty, the only option is to insert all characters of str1
                dp[i][j] = i
            elif str1[i-1] == str2[j-1]:
                # If last character of both strings matches
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                # If last character matches, consider both cases and take the minimum
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + 1

    # Required answer is in dp[m][n]
    return dp[m][n]
