def maximum_segments(n, a, b, c):
    i = n
    while i >= max(a, b, c):
        if i % max(a, b, c) == 0:
            segments = i // max(a, b, c)
            i -= segments * max(a, b, c)
            if i == 0:
                return segments + 1
        else:
            i -= 1
    return 0
