def maximum_segments(n, a, b, c):
    dp = [[0 for i in range(c+1)] for i in range(n+1)]
    for i in range(1, n+1):
        for j in range(1, c+1):
            if j >= a:
                dp[i][j] = dp[i-1][j] or dp[i-1][j-a]
            if j >= b:
                dp[i][j] = dp[i][j] or dp[i-1][j-b]
            if j >= c:
                dp[i][j] = dp[i][j] or dp[i-1][j-c]
    return dp[n][c]
