def get_Pairs_Count(arr, target_sum, unique=False):
  # Map to store the occurrences of each element
  count_map = {}
  pairs = 0

  # Count occurrences of each element
  for num in arr:
    if num not in count_map:
      count_map[num] = 0
    count_map[num] += 1

  # Check for pairs
  for num in count_map:
    # If unique is True, we only count pairs where the numbers are the same
    if unique and num == target_sum // 2:
      pairs += count_map[num] * (count_map[num] - 1) // 2
    else:
      if target_sum - num in count_map:
        pairs += count_map[num] * count_map[target_sum - num]

  return pairs
```

