def min_cost(cost, m, n):
    dp = [[0]*n for _ in range(m)]  # Initialize the DP table

    # Base case
    dp[0][0] = cost[0][0]

    # Fill the DP table for first row
    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + cost[0][j]

    # Fill the DP table for first column
    for i in range(1, m):
        dp[i][0] = dp[i-1][0] + cost[i][0]

    # Fill the DP table for rest of the matrix
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + cost[i][j]

    return dp[m-1][n-1]  # Return the minimum cost path to (m, n)
