def jacobsthal_num(n):
    # Base cases
    if n == 0:
        return 0
    if n == 1:
        return 1

    # Recursive formula to calculate Jacobsthal numbers
    else:
        return 2 * jacobsthal_num(n - 1) + jacobsthal_num(n - 2)
