def set_Right_most_Unset_Bit(x):
    # Check if the input number is 0
    if x == 0:
        return 1

    # Calculate the position of the rightmost unset bit
    position = 0
    while (x >> position) & 1 == 1:
        position += 1

    # Set the rightmost unset bit
    return x | (1 << position)
