def set_Right_most_Unset_Bit(number):
    # Check if number is 0
    if number == 0:
        return 1

    # Find the rightmost unset bit
    right_most_unset = (number | (number + 1)) & ~(number + 1)

    # Return number plus one if the rightmost bit was 1 before, otherwise return number
    return number + int(bool(right_most_unset & 1))
