from itertools import permutations

def maxAverageOfPath(matrix, n):
    def calculate_average(path):
        return sum(matrix[i][j] for i, j in path) / len(path)

    def is_valid_path(path):
        return len(set(tuple(path))) == n

    max_average = 0
    for perm in permutations(range(n)):
        if is_valid_path(perm):
            current_average = calculate_average(perm)
            if current_average > max_average:
                max_average = current_average
    return max_average
