def maxAverageOfPath(matrix, n):
    max_sum = float('-inf')

    # Iterate through all possible starting points
    for i in range(n):
        for j in range(n):
            # Calculate the sum of all elements in a path starting from (i, j)
            path_sum = 0
            for k1 in range(n):
                for k2 in range(n):
                    path_sum += matrix[k1][k2]
