def maxAverageOfPath(matrix, n):
    # Calculate all possible paths and their average values
    paths = []
    for i in range(n):
        for j in range(n):
            path = []
            # Left path
            for x in range(j, -1, -1):
                path.append(matrix[i][x])
            # Right path
            for x in range(j, n):
                path.append(matrix[i][x])
            # Up path
            for y in range(i, -1, -1):
                path.append(matrix[y][j])
            # Down path
            for y in range(i, n):
                path.append(matrix[y][j])
            paths.append(path)
    # Find the path with the maximum average
    max_average = -float('inf')
    best_path = []
    for path in paths:
        average = sum(path) / len(path)
        if average > max_average:
            max_average = average
            best_path = path
    return max_average
```

