    local_maxes = [i for i in range(len(arr))]
    max_count = 0

    # Fill the local maximums array
    for i in range(len(arr)):
        for j in range(i):
            if arr[j] < arr[i] and local_maxes[j] > local_maxes[i]:
                local_maxes[i] = local_maxes[j]

    # Create a reversed copy of the array
    arr = arr[::-1]
    max_count = 0

    # Fill the local maximums array for the reversed array
    for i in range(len(arr)):
        for j in range(i):
            if arr[j] < arr[i] and local_maxes[j] > local_maxes[i]:
                local_maxes[i] = local_maxes[j]

    # Find the LIS for the local maximums array
    lis = [1] * len(local_maxes)
    for i in range(1, len(lis)):
        for j in range(i):
            if local_maxes[j] < local_maxes[i] and lis[i] < lis[j] + 1:
