def lbs(sequence):
    n = len(sequence)
    LIS = [1] * n                  # Initialize LIS array with 1s
    LDS = [1] * n                  # Initialize LDS array with 1s

    # Compute the length of the longest increasing subsequence ending at each element
    for i in range(1, n):
        for j in range(i):
            if sequence[i] > sequence[j]:
                LIS[i] = max(LIS[i], LIS[j] + 1)

    # Compute the length of the longest decreasing subsequence starting at each element
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if sequence[i] > sequence[j]:
                LDS[i] = max(LDS[i], LDS[j] + 1)

    # The length of the longest bitonic subsequence is the maximum of the corresponding elements in LIS and LDS arrays
    return max([LIS[i] + LDS[i] - 1 for i in range(n)])

