        return 0

    len_arr = len(arr)
    ans = [1]*len_arr
    increasing = [True]*len_arr

    for i in range(1, len_arr):
        for j in range(i):
            if arr[j] < arr[i]:
                ans[i] = max(ans[i], ans[j] + 1)
        if arr[i] > arr[i-1]:
            increasing[i] = increasing[i-1]

    decreasing = [1]*len_arr
    ans_max = 1
    for i in range(len_arr-2, -1, -1):
        for j in range(i+1, len_arr):
            if arr[j] < arr[i]:
                decreasing[i] = max(decreasing[i], decreasing[j] + 1)
        if arr[i] > arr[i+1]:
            increasing[i] = increasing[i+1]
        ans_max = max(ans_max, increasing[i]+decreasing[i]-1)

