def dealnnoy_num(n, k):
    # Base case
    if n == 0 and k == 0:
        return 1
    # Initialize the matrix for Pascal's triangle
    triangle = [[0 for i in range(k+1)] for j in range(n+1)]
    # Fill the triangle based on Pascal's principle
    for i in range(n+1):
        for j in range(min(i, k)+1):
            if j == 0 or j == i:
                triangle[i][j] = 1
            else:
                triangle[i][j] = triangle[i-1][j] + triangle[i-1][j-1]
    # The nth delannoy number is the number in the nth row and kth column of the triangle
    return triangle[n][k]
```

