def dealnnoy_num(n, k):
    # Base case: the first delannoy number for n and k is 1
    if n == 0 and k == 0:
        return 1
    # Base case: n is 1 and k can be 0 or 1
    elif n == 1:
        return 1 if k == 0 else k + 1
    else:
        return dealnnoy_num(n-1, k) + dealnnoy_num(n-1, k-1)
