def delnnoy_num(n, k):
    # Base case: if n is 0, there's only one delnoy number i.e., 1
    if n == 0:
        return 1
    # Base case: if k is 0, there's only one delnoy number i.e., 1 (single element subset)
    elif k == 0:
        return 1
    # Recursive calculation of delnoy number
    else:
        return delnnoy_num(n-1, k-1) + delnnoy_num(n-1, k) + delnnoy_num(n, k-1)
