def remove_parenthesis(s):
    # Start with an index to track the position of the next character to replace
    i = 0
    result = []

    # Iterate through each character in the string
    while i < len(s):
        # If the character is an opening parenthesis, increase the index for both position and result
        if s[i] == '(':
            i += 2
        # If the character is a closing parenthesis, decrement the index for the result
        elif s[i] == ')':
            i -= 1
        # For any other character, directly append it to the result
        else:
            result.append(s[i])
            i += 1

    # Join the result list into a string and return it
    return ''.join(result)
```

