def find_Min_Swaps(arr,n):
  # Counting 1's and 0's
  c1, c0 = 0, 0
  for i in range(n):
    if arr[i] == 1:
      c1 += 1
    else:
      c0 += 1
  # If all elements are 1s or all are 0s...
  if c1 == n or c0 == n:
      return 0
  # Finding the maximum number of zeros (0's allowed) in the rotated array
  c0_max, c0_left = 0, 0
  for i in range(n):
    if arr[i] == 0:
      c0_left += 1
      if c0_left > c0_max:
        c0_max = c0_left
  return n-c0_max
```

