def find_Min_Swaps(binary_array, size):
    swaps = 0
    for i in range(size):
        # If the current element is not 0, it means it should be the start of a swap sequence
        if binary_array[i] == 0:
            start = i
            # Find the next 1 that follows the current sequence
            for j in range(start + 1, size):
                if binary_array[j] == 1:
                    # Swap the elements
                    binary_array[start], binary_array[j] = binary_array[j], binary_array[start]
                    swaps += 1
                    break
    return swaps
