def find_Min_Swaps(array,n):
    swaps = 0
    for i in range(n):
        if array[i] == 1:
            k = i+1
            a = 1
            l = 0
            while a < n:
                if array[a] == 0:
                    a += 1
            else:
                while k < n:
                    a = i
                    l = k
                    while a < l:
                        array[a],array[l] = array[l],array[a]
                        l -= 1
                        a += 1
                        swaps += 1
    return swaps
