def maxAverageOfPath(matrix, n):
    # Initialize variables to store the maximum average and the maximum path found
    max_avg = 0
    max_path = []

    # Iterate through possible starting positions for the path
    for i in range(n):
        for j in range(n):
            # Helper function to find the average of a path passing through a given position
            def find_path_average(x, y, path):
                if x < 0 or y < 0 or x >= n or y >= n:
                    return float('-inf')

                # Check if the current position is already in the path
                for p in path:
                    if p == (x, y):
                        return float('-inf')

                # If the path is of length 1, return the value of the current position
                if len(path) == 1:
                    return matrix[x][y]

                # Recursively find the average of paths starting from all adjacent positions
                path.append((x, y))
