def min_cost(cost, m, n):
    # Base case: if we are at the top-left corner, the cost is 0
    if m == 0 and n == 0:
        return cost[0][0]

    # If we are out of bounds, return a large value
    if m < 0 or n < 0:
        return float('inf')

    # If the value at the current cell is undefined, calculate it
    if cost[m][n] == -1:
        # Recur for all possible paths (left and up) and return the minimum cost
        cost[m][n] = min(min_cost(cost, m-1, n), min_cost(cost, m, n-1)) + cost[m][n]

    return cost[m][n]
```

