# define the function to find the minimum cost path
def min_cost(cost, m, n):
    # create a grid to store minimum cost to reach each cell
    dp = [[float('inf')] * (n+1) for _ in range(m+1)]

    # base case: minimum cost to reach (0, 0) is the value of cost[0][0]
    dp[0][0] = cost[0][0]

    # fill the dp grid
    for i in range(m+1):
        for j in range(n+1):
            # update the cost of reaching (i, j) by considering the minimum cost of reaching its neighboring cells
            if i>0: dp[i][j] = min(dp[i][j], dp[i-1][j] + cost[i][j])
            if j>0: dp[i][j] = min(dp[i][j], dp[i][j-1] + cost[i][j])

    # the minimum cost to reach (m, n) is stored in dp[m][n]
    return dp[m][n]
```

