def super_seq(str1, str2, N, M):
    # Create a 2D array dp to store lengths of the longest common subsequences
    dp = [[0 for _ in range(M+1)] for _ in range(N+1)]

    # Build dp array from bottom up
    for i in range(1, N+1):
        for j in range(1, M+1):
            if str1[i-1] == str2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    # The length of the shortest supersequence is the sum of lengths of both strings minus their LCS
    return N + M - dp[N][M]
