    # If the middle element is the target element, return its index
    if arr[mid] == x and (mid == high or arr[mid + 1] != x):
        return mid
    # If the x is greater than the middle element, search the right half
    elif x > arr[mid]:
        return last(arr, x, mid + 1, high)
    # If x is less than the middle element, search the left half
    else:
        return last(arr, x, low, mid - 1)
