    # If low exceeds high, return -1 indicating the element is not found
    if low > high:
        return -1
    # Calculate the middle index
    mid = (low + high) // 2
    # If the middle element matches the target, return the middle index
    if arr[mid] == high:
        return mid
    # If the target element is greater than the middle element, search in the right half
    elif high > arr[mid]:
        return last(arr, mid + 1, high)
    # If the target element is less than the middle element, search in the left half
    else:
        return last(arr, low, mid - 1)
