def is_polite(n):
    def euler_totient(x):
        count = 0
        for i in range(1, x):
            if x % i == 0:
                count += 1
        return count
    def is_obstructed(x):
        prime_numbers = {2, 3, 5, 7}  # Initial set of prime numbers
        while True:
            if euler_totient(x) >= x + 1:
                break
            x += 1
            s = 2
            while s * s <= x:
                if x % s == 0:
                    while x % s == 0:
                        prime_numbers.add(s)
                        x //= s
                    s += 1
            if x > 2:
                prime_numbers.add(x)
        return sum(prime_numbers) > x

    t = 2
    while n > 0:
        if not is_obstructed(t):
            n -= 1
        t += 1
    return t - 1
