def unique_sublists(lst):
    # Create an empty dictionary to store unique sublists and their frequencies
    freq_dict = {}
    for subList in lst:
        # Convert the subList to a tuple to make it hashable
        sortedTuple = tuple(sorted(subList))
        # If the sortedTuple is already in the dictionary, increment its count
        if sortedTuple in freq_dict:
            freq_dict[sortedTuple] += 1
        else:
            # Otherwise, add the sortedTuple to the dictionary with a count of 1
            freq_dict[sortedTuple] = 1
    # Create a new dictionary to store the unique sublists
    unique_dicts = {}
    # Iterate over the dictionary with frequency
    for subTuple, freq in freq_dict.items():
        # If the frequency is 1, add the original subList to the unique dictionary
        if freq == 1:
            unique_dicts[subTuple] = subTuple
    return unique_dicts
