```python
import math

def get_ludic(n):
    """Return a list containing all lucid numbers less than or equal to n."""
    def is_ludic(num):
        """Check if a number is a lucid number."""
        return all(math.gcd(i, num) == 1 for i in range(1, num))

    l = []
    i = n - 1
    while i >= 1:
        if is_ludic(i):
            l.append(i)
        i -= 1
    return l[::-1]
```

