def find_closet(arr1, arr2, arr3, m, n, p):
    min_diff = float('inf')
    res = []

    # Loop through all combinations of three elements from all three arrays
    for i in range(m):
        for j in range(n):
            for k in range(p):
                diff = abs(arr1[i] - arr2[j] + arr3[k])

                # If the current difference is less than the minimum difference found so far, update res and min_diff
                if diff < min_diff:
                    min_diff = diff
                    res = [arr1[i], arr2[j], arr3[k]]

    # Return the closest three elements
    return tuple(res)
