        return find_kth(arr2, arr1, m, n, k)
    # If k is 1, return the first element of the array
    if k == 1:
        return min(arr1[0], arr2[0])
    # Find the middle element of both arrays
    x = min(n // 2, k // 2)
    y = min(m // 2, k // 2)
    if arr1[x] < arr2[y]:
        # If the middle element of the first array is less than the middle element of the second array
        # Then the kth element must be in the remaining part of the array1
        return find_kth(arr1[x+1:], arr2, n - x - 1, m, k - x - 1)
    else:
        # If the middle element of the first array is greater than the middle element of the second array
        # Then the kth element must be in the remaining part of the array2
