def count_duplic(sequence):
    count = []  # To store the frequency of each element
    prev = None  # To store the previous element for comparison
    freq = 1  # To store the frequency of the previous element

    for element in sequence:
        if element == prev:
            freq += 1  # Increment frequency if the element is the same as the previous
        else:
            if prev is not None:
                count.append((prev, freq))  # Add the previous element and its frequency to the count list
            prev = element  # Update prev to the current element
            freq = 1  # Reset frequency for the new element

    # Adding the last element's frequency to the count list (in case it is a new element)
    if prev is not None:
        count.append((prev, freq))

    return sequence, count
