def get_Pairs_Count(arr, n, sum):
    # Initialize a dictionary to store the frequency of each element in the array
    res_map = {}
    # Traverse through each element in the array
    for i in range(n):
        # If the difference between the sum and the current element is already in the map
        if ((sum - arr[i]) in res_map):
            # Add the frequency of the difference to the result
            res_map[sum - arr[i]] += 1
        # Otherwise, add the current element to the map with a frequency of 1
        else:
            res_map[arr[i]] = 1
    # Calculate the number of pairs whose sum is equal to the given sum
    count = 0
    for i in range(n):
        if (arr[i] in res_map):
            # If the current element is not present in the map, then skip to the next element
            if (arr[i] == sum - arr[i]):
                # If the current element and the difference are the same but their frequency is greater than 1, add their count to the result
                if (res_map[arr[i]] >= 2):
                    count += res_map[arr[i]] * (res_map[arr[i]] - 1) // 2
                else:
                    count += res_map[arr[i]]
            # If the current element is present in the map, then add their count to the result
            else:
                count += res_map[arr[i]] * res_map[sum - arr[i]]
    # Return the total count of pairs
    return count
