def find_Max(nums, start, end):
    # If there is only one element left, it is the maximum
    if start == end:
        return nums[start]
    else:
        # Find the middle index
        mid = (start + end) // 2
        # If the middle element is greater than its previous element, it is the maximum
        if nums[mid] > nums[mid - 1]:
            return nums[mid]
        # If the middle element is less than its next element, it is the maximum
        elif nums[mid] < nums[mid + 1]:
            return nums[mid + 1]
        # If the left part is sorted
        if nums[start] < nums[mid]:
            # The maximum element is in the right part
            return find_Max(nums, mid + 1, end)
        # If the right part is sorted
        else:
            # The maximum element is in the left part
            return find_Max(nums, start, mid - 1)
