def move_zero(nums):
    # Separate all zeroes from the list and collect them
    zeroes = [num for num in nums if num == 0]
    # Replace all zeroes in the list with None to facilitate removal
    for i, num in enumerate(nums):
        if num == 0:
            nums[i] = None
    # Collect all the None values that are not in the zeroes list back into zeroes list
    zeroes += [num for num in nums if num is not None]
    # Replace None values back in the list
    for i, num in enumerate(nums):
        if nums[i] is None:
            nums[i] = zeroes.pop(0)
    return nums
