    sum_of_primes = 0
    prime = [True for i in range(n+1)]
    p = 2
    while (p * p <= n):
        # If prime[p] is true, then update all multiples of p
        if (prime[p] == True):
            for i in range(p * p, n+1, p):
                prime[i] = False
        p += 1
    # Calculate the sum of prime numbers
    for p in range(2, n):
        if prime[p]:
            sum_of_primes += p
    return sum_of_primes
