def max_sum_of_three_consecutive(arr, N):
    # Handle the case when there are less than 3 elements
    if N < 3:
        return 0

    # Initialize the dp array where dp[i] will store the maximum sum ending with arr[i]
    dp = [0] * N

    # Fill the dp array
    for i in range(2, N):
        dp[i] = max(arr[i] + dp[i-3], dp[i-1])

    # The result will be the maximum of dp[i] for i ranging from 2 to N-1
    return max(dp[i] for i in range(2, N))
