def max_sum_of_three_consecutive(arr, n):
    # Initialize the base cases
    if n < 3:
        return 0
    if n == 3:
        return max(arr)

    # Initialize the dp array with zeros
    dp = [0] * n
    dp[0], dp[1], dp[2] = arr[0], arr[0] + arr[1], arr[0] + arr[1] + arr[2]

    # Fill the dp array
    for i in range(3, n):
        dp[i] = max(arr[i] + dp[i-3], dp[i-2])

    # The maximum sum will be in the last three elements of the dp array
    return max(dp[n-3], dp[n-2], dp[n-1])
