    for i in range(1, n):
        for j in range(i):
            if a[i] > a[j] and inc[i] < inc[j] + 1:
                inc[i] = inc[j] + 1

    # Build decreasing subsequence lengths from right to left
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if a[i] > a[j] and dec[i] < dec[j] + 1:
                dec[i] = dec[j] + 1

    # The longest bitonic subsequence is the maximum value in the sum of the best increasing and decreasing subsequences at each position
    lls = [inc[i] + dec[i] - 1 for i in range(n)]
