def lbs(arr):
    n = len(arr)
    lis = [1] * n
    rls = [1] * n

    # Compute lis values in bottom up manner
    for i in range(1, n):
        for j in range(0, i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # Compute rls values in bottom up manner from right to left
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if arr[i] > arr[j] and rls[i] < rls[j] + 1:
                rls[i] = rls[j] + 1

    # Find the max length of the longest bitonic subsequence
    max_len = max(lis[i] + rls[i] - 1 for i in range(n))

    return max_len

