def min_Swaps(s1, s2):
    n = len(s1)
    swaps = 0
    for i in range(n):
        if s1[i] != s2[i]:
            misplaced = False
            for j in range(i+1, n):
                if s1[j] == s2[i]:
                    swaps += 1
                    misplaced = True
                    break
            if not misplaced:
                return -1  # Impossible to convert if no suitable place of misplaced element is found
    return swaps
