def min_Swaps(str1, str2):
    # If lengths of both strings are not equal, it's impossible to convert
    if len(str1) != len(str2):
        return -1
    # Create a dictionary to count the frequency of each character in str2
    char_freq = {}
    for char in str2:
        if char in char_freq:
            char_freq[char] += 1
        else:
            char_freq[char] = 1
    # Create a stack to keep track of characters that may disrupt the conversion
    stack = []
    for char in str1:
        if char not in char_freq:
            stack.append(char)
        else:
            if char_freq[char] > 0:
                char_freq[char] -= 1
            else:
                # If the frequency is 0, pop the character from the stack as it is no longer needed
                stack.pop()
    # The number of swaps required is equal to the number of characters in the stack
    return len(stack)
