def max_product(numbers): 
    # Initialize the maximum negative and positive products
    max_neg1, max_neg2, max_pos1, max_pos2 = float('-inf'), float('-inf'), 0, 0

    # Iterate through the array to find the maximum product of two integers
    for num in numbers: 
        if num > max_pos1:
            max_pos2, max_pos1 = max_pos1, num
        elif num > max_pos2:
            max_pos2 = num

        if num < 0: 
            if num > max_neg1:
                max_neg2, max_neg1 = max_neg1, num
            elif num > max_neg2:
                max_neg2 = num

    # If there are at least two positive numbers, return the maximum product of two
    if max_pos1 > 0 and max_pos2 > 0:
        return (max_pos1, max_pos2)
    # If there is at least one negative number and one positive number, return the maximum of negative products and positive product
    elif max_neg1 > 0 and max_pos1 > 0:
        return (max_neg1, max_pos1)
    else:
        # If all numbers are non-positive, return the minimum product (which could be zero if array contains all negatives)
        return (min(min(numbers), 0), max(numbers))
