def max_sum_pair_diff_lessthan_K(arr, n, k):
    # Define a recursive function to calculate the maximum sum
    def helper(arr, n, k, start):
        # Base case: if no element is left
        if start >= n:
            return 0
        # Check if the current element is within the range
        if arr[start] <= k:
            # Recursive case: include the current element and skip next if it fits
            return arr[start] + helper(arr, n, k, start + 2) if start + 2 < n else arr[start]
        # Skip the current element
        return helper(arr, n, k, start + 1)

    # Call the recursive function with the initial parameters
    return helper(arr, n, k, 0)
