    excl=[1]*len(a)  # Length of Longest Decreasing Subsequence ending at i
    l=0         # Length of Longest Bitonic Subsequence
    # For every element find the length of increasing subsequence and storing it in incl[]
    for i in range(1,len(a)):
        for j in range(i):
            if a[i]>a[j]:
                incl[i]=max(incl[i],incl[j]+1)
    # For every element find the length of decreasing subsequence and storing it in excl[]
    for i in range(len(a)-1,-1,-1):
        for j in range(len(a)-1,i-1,-1):
            if a[i]>a[j]:
                excl[i]=max(excl[i],excl[j]+1)
    # For every index compare the value stored in incl[] and excl[]
