    down = [1] * len(arr)  # for max length subsequence downwards

    # compute max length subsequence upwards, from both end to the centre
    for i in range(len(arr) - 1, 0, -1):
        for j in range(i):
            if arr[j] < arr[i]:
                up[i] = max(up[i], up[j]+1)

