    increasing, decreasing, len_lbs = [], [], 0

    # Iterate through the array to find the increasing subsequence
    for num in nums:
        if not increasing or num > increasing[-1]:
            increasing.append(num)
        else:
            right = bisect.bisect_right(decreasing, num)
            if right:
                increasing[right-1] = num
            else:
                increasing.append(num)

    # The length of the longest bitonic sequence is the length of the longest increasing subsequence plus the length of the longest decreasing subsequence minus the overlap
    len_lbs = len(increasing) + len(decreasing) - bisect.bisect_right(decreasing, increasing[-1])

    return len_lbs
