def min_cost(cost, m, n):
    # Transform the bottom-right corner element to 0
    cost[m-1][n-1] = 0

    # Traverse the matrix from the bottom-right to the top-left
    for i in range(m-1, -1, -1):
        for j in range(n-1, -1, -1):
            # If the current element is at the edge (rightmost or bottommost)
            if i == m-1:
                # The cost is the sum of the right value from the element below it
                cost[i][j] += cost[i+1][j]
            elif j == n-1:
                # The cost is the sum of the bottom value from the element to the right of it
                cost[i][j] += cost[i][j+1]
            else:
                # The cost is the minimum of the elements diagonally above, to the left, and below
                cost[i][j] += min(cost[i+1][j], cost[i][j+1], cost[i+1][j+1])

    # Return the minimum cost to reach (m-1, n-1)
    return cost[0][0]
```

```python
def min_cost(cost, m, n):
    # Base case: if it's at the starting point, return the cost of itself
    if m == 0 and n == 0:
        return cost[0][0]
    # If it's outside the bounds, return a large number (assuming it's unreachable)
    if m < 0 or n < 0:
        return float('inf')
    # Recurrence relation: choose the minimum cost of the current cell plus the minimum cost of the cell below and to the left
    return cost[m][n] + min(min_cost(cost, m-1, n), min_cost(cost, m, n-1))
```

