def min_cost(cost, m, n):
  if m<=0 or n<=0:
    return 'Invalid input'
  dp = [[float('inf') for i in range(n+1)] for j in range(m+1)]
  dp[0][0] = cost[0][0]

  for i in range(1, m+1):
    for j in range(1, n+1):
      dp[i][j] = min(dp[i][j-1] + cost[i-1][j-1], dp[i-1][j] + cost[i-1][j-1])
  return dp[m][n]
```

