def calculate_combination(n, r):
    # Function to compute binomial coefficient C(n, r)
    if r > n:
        return 0
    if r == 0 or r == n:
        return 1
    memo = {}
    return memo.get((n, r), (memo[(r, n)] = calculate_combination(r, n-r) + calculate_combination(r-1, n-r)))

