def find_kth(A, B, i, j, k):
    # If only one array is left
    if len(A) == 1:
        return A[i]
    if len(B) == 1:
        return B[j]
    mid_A = A[len(A) // 2]
    mid_B = B[len(B) // 2]
    # If the sum index 'k' is position-1, then either one element
    # has been picked from both array. Choose the minimum of those two
    if mid_B == k - 1:
        return min(mid_A, mid_B)
    # If element at (i + len(A) // 2) of array 'A' is smaller than
    # equal to the element at (j + mid_B) of array 'B', then element
    # at position 'k' will also be appearance in both arrays from position
    # mid_A + 1 of 'A' and position mid_B + 1 of 'B'
    elif mid_A <= mid_B:
        return find_kth(A[mid_A + 1:], B, i, j + mid_A + 1, k - mid_A - 1)
    # Start search from opposite positions
    else:
        return find_kth(A, B, i + mid_B + 1, j, k - mid_B - 1)
