def min_coins(coins, n, total):
    # Create a 2D array to store the minimum number of coins for each amount from 0 to total
    dp = [[float('inf')] * (total + 1) for _ in range(n + 1)]

    # Base case: to make a value of 0, we need 0 coins
    for i in range(n + 1):
        dp[i][0] = 0

    # Fill the dp array
    for i in range(1, n + 1):
        for j in range(1, total + 1):
            if coins[i - 1] <= j:
                dp[i][j] = min(dp[i][j], dp[i - 1][j] + 1, dp[i][j - coins[i - 1]])
            else:
                dp[i][j] = dp[i - 1][j]

    # The minimum number of coins for the given total
    return dp[n][total]
```

