def min_coins(coins, v, n):
    dp = [[float('inf') for _ in range(v+1)] for _ in range(n+1)]

    # Base case
    for i in range(n+1):
        dp[i][0] = 0

    # Fill the DP table
    for i in range(1, n+1):
        for j in range(1, v+1):
            if coins[i-1] <= j:
                dp[i][j] = min(dp[i-1][j], dp[i][j-coins[i-1]] + 1)
            else:
                dp[i][j] = dp[i-1][j]

    return dp[n][v]
```

