    freq = {}
    result = []
    prev_element = None
    count = 0

    for i, num in enumerate(nums):
        # Edge case for the first element
        if i == 0:
            freq[num] = 1
            prev_element = num
            count += 1
        else:
            # If the current element is the same as the previous one
            if num == prev_element:
