def count_duplic(data):
    if not data:  # If the list is empty, return an empty array
        return ([], [])

    # Initialize empty lists to store non-duplicate and duplicate elements
    non_dups = []
    dups = []

    # Iterate through the list to find consecutive duplicates
    for i in range(len(data)-1):
        if data[i] == data[i+1]:
            dups.append(data[i])
        else:
            non_dups.append(data[i])

    # Append the last remaining element if it's not a duplicate
    if data[-1] not in dups:
        non_dups.append(data[-1])

    return (non_dups, dups)
