def super_seq(str1, str2, m, n):
    # Create a 2D table to store lengths of the longest common subsequences
    LCS = [[0] * (n+1) for i in range(m+1)]

    # Fill the LCS table
    for i in range(1, m+1):
        for j in range(1, n+1):
            if str1[i-1] == str2[j-1]:
                LCS[i][j] = 1 + LCS[i-1][j-1]
