def find_Max(arr,l,r):
    # If array is monotonic, which means it doesn't contain any 
    # rotations, then the maximum will be at the end
    if l == r: 
        return arr[l]
    mid = l + (r-l)//2
    # If mid element is greater than its previous element and smaller than 
    # its next element, 
    # then mid is the maximum element
    if arr[mid] > arr[mid-1] and arr[mid] < arr[mid+1]: 
        return arr[mid] 

    # If the array is not monotonic, then 
    # max element is either in the left half or right half
    if arr[mid] < arr[l]: 
        return find_Max(arr, l, mid-1) 
    else: 
        return find_Max(arr, mid+1, r)
