def coin_change(coins, amount, n):
    # Initializing a 2D list with 0s
    dp = [[0 for i in range(n + 1)] for i in range(amount + 1)]

    # Base case: If amount is 0, only one way to make it (choose no coins)
    for i in range(n + 1):
        dp[0][i] = 1

    # Filling the dp array
    for coin in coins:
        for x in range(1, amount + 1):
            if x >= coin:
                dp[x][i] = dp[x][i - coin] + dp[x][i]
            else:
                dp[x][i] = dp[x][i - 0]

    # Required output
    return dp[amount][n]
