def coin_change(coins, m, V):
    # Initialize a 2D DP array to store the minimum number of coins needed
    dp = [[0 for x in range(V+1)] for x in range(m+1)]

    # We will traverse through all items and all possible amount
    for i in range(m+1):
        for j in range(V+1):
            # If amount is 0, no coins are needed
            if j == 0:
                dp[i][j] = 0
            # If current item (coin) is more than the amount, then we can't include it
            elif coins[i-1] > j:
                dp[i][j] = dp[i-1][j]
            # If current item (coin) is less than or equal to the amount, we can include it or not include it
            else:
                dp[i][j] = min(dp[i-1][j], 1 + dp[i][j-coins[i-1]])

    # The result will be in the bottom-right corner of the dp array
    return dp[m][V]
