def rencontres_number(n, k):
    # This is an optimized solution using dynamic programming to find the nth rencontres number.
    # The memoization technique reduces the time complexity significantly.
    def dp memo(n, k, memo):
        if (n, k) in memo:
            return memo[n, k]

        if k == n - 1:
            return 1
        if k == 0:
            return 1
        res = dp(memo, n - 1, memo) * (n - k - 1) / k
        memo[n, k] = res
        return res

    return int(dp(memo, n, {}))
```

