def sum_of_prime_divisors(n):
    factors = []
    # Divide n by 2 to remove all even factors
    while n % 2 == 0:
        factors.append(2)
        n = n // 2
    # n must be odd at this point, so we can skip one element (Note i = i +2)
    for i in range(3, int(n**0.5)+1, 2):
        # While i divides n, add i and divide n
        while n % i == 0:
            factors.append(i)
            n = n // i
    # This condition is to handle the case when n is a prime number greater than 2
    if n > 2:
        factors.append(n)

    # Calculate the sum of all unique prime factors
    unique_sums = set()
    for factor in factors:
        if factor > 1:  # Excluding the case where factor is 1 (which is not prime)
            unique_sums.add(factor)
    return sum(unique_sums)

