def maxAverageOfPath(matrix, n):
    # Check if the given matrix is empty or not
    if not matrix or n == 0:
        return 0

    # Prepare the dp table as 0 since no movements are possible or needed
    dp = [[0] * n for _ in range(n)]

    # Fill the dp table with the max average path for each cell
    for i in range(n):
        for j in range(n):
            # If it is the first cell, the average is the cell value itself
            if i == 0 and j == 0:
                dp[i][j] = matrix[i][j] / 1
            # If it is the first row, the average is the sum of cells to the left
            elif i == 0:
                dp[i][j] = sum(matrix[i][k] / (k+1) for k in range(j+1)) / (j+1)
            # If it is the first column, the average is the sum of cells above
            elif j == 0:
                dp[i][j] = sum(matrix[k][j] / (k+1) for k in range(i+1)) / (i+1)
            # If it is not the first cell of the matrix, the average is the average of cells to the left, above, and diagonally previous
            else:
                dp[i][j] = (dp[i-1][j] + dp[i][j-1] + dp[i-1][j-1] + matrix[i][j]) / 4

    # Find the maximum average path from the top right corner to the bottom left corner
    return max(dp[-1][-1])
