def maxAverageOfPath(matrix, n):
    # Helper function to calculate the sum of all elements in a path
    def path_sum(x, y, path):
        if not (0 <= x < n and 0 <= y < n):
            return 0
        # if reached the bottom-right corner, calculate the average
        if x == n-1 and y == n-1:
            return path_sum(n-1, n-1, [matrix[n-1][n-1]])
        # calculate the sum of the current cell and the maximum path sum of the next two cells
        return matrix[x][y] + max(path_sum(x+1, y, path+[matrix[x][y]]), path_sum(x, y+1, path+[matrix[x][y]]))

    # Find the maximum path sum starting from any cell
    max_path_sum = 0
    for i in range(n):
        for j in range(n):
            max_path_sum = max(max_path_sum, path_sum(i, j, [matrix[i][j]]))
    return max_path_sum / float(n*n)
