def sum_of_square(n):
    # Initialize a list to store binomial coefficients
    coefficients = [0] * (n + 1)

    # Calculate binomial coefficients using Pascal's triangle
    for i in range(n + 1):
        for j in range(i + 1):
            if j == 0 or j == i:
                coefficients[j] = 1
            else:
                coefficients[j] = coefficients[j] + coefficients[j - 1]

    # Calculate the sum of squares of binomial coefficients
    square_sum = 0
    for i in range(n + 1):
        square_sum += coefficients[i] ** 2

    return square_sum
