def prime_factorize(n):
    factorization = {}
    # Divide n by 2 to find factors of 2
    while n % 2 == 0:
        if 2 in factorization:
            factorization[2] += 1
        else:
            factorization[2] = 1
        n = n // 2
    # Divide n by odd numbers to find other factors
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            if i in factorization:
                factorization[i] += 1
            else:
                factorization[i] = 1
            n = n // i
    # If n is a prime number greater than 2
    if n > 2:
        if n in factorization:
            factorization[n] += 1
