    temp = n

    # Find all prime factors of n
    while(temp > 1):
        if(is_prime(temp)):
            if temp not in prime_fac:
                prime_fac.append(temp)
            temp //= temp
        else:
            temp += 1

    # Count the distinct powers of prime factors
    count = 0
    for factor in prime_fac:
        count += math.floor(math.log(n, factor))

