def join_tuples(list_of_tuples):
    unique_tuples = []
    initial_elements = set()
    # Extracting initial elements of the tuples
    for tup in list_of_tuples:
        initial_elements.add(tup[0])

    # Iterating over tuples to join similar initial elements
    for tup in list_of_tuples:
        if tup[0] in initial_elements and tup not in unique_tuples:
