def join_tuples(list_of_tuples):
    # To store merged tuples
    result = []
    # To keep track of the next element to merge
    next_element = None

    for tuple_elements in list_of_tuples:
        # If next_element is None, we start with the current tuple
        if next_element is None:
            result.append(tuple_elements)
        else:
            # If the first element of the current tuple matches the next element, merge them
            if tuple_elements[0] == next_element[0]:
                result[-1] += tuple_elements[1:]
            else:
                result.append(tuple_elements)
        # Move to the next element in a tuple
        next_element = tuple_elements[1]

    return result
