# Function to calculate the nth Delannoy number
def dealnnoy_num(n, m):
    # Base cases
    if n < 0 or m < 0:
        return 0
    # Initialize the table for memoization
    table = [[0 for _ in range(m+1)] for _ in range(n+1)]
    # Fill the table
    for i in range(n+1):
        for j in range(m+1):
            if i == 0 or j == 0:
                table[i][j] = 1
            else:
                table[i][j] = table[i-1][j] + table[i-1][j-1]
    # The result is in the table at [n][m]
    return table[n][m]
