import functools
def coin_change(coins, n, m):
    @functools.lru_cache(None)
    def dp(i, j):
        if i == 0:
            return 1
        if j == 0:
            return 1
        if i < 0 or j < 0:
            return 0
        return dp(i-1, j) + dp(i, j-coins[i-1])
    return dp(n, m)
