def min_Swaps(str1, str2):
    # Find indexes and count of all '0's in str1 and '1's in str1
    x = [i for i, j in enumerate(str1) if j == '0']
    y = [i for i, j in enumerate(str2) if j == '1']

    # Find indexes and count of all '1's in str1 and '0's in str2
    v = [i for i, j in enumerate(str1) if j == '1']
    w = [i for i, j in enumerate(str2) if j == '0']

    # If both x and v sorted are equal then no swaps are required
    if sorted(x) == sorted(v):
        return 0
    else:
        # Use Modified Gale-Shapley algorithm to find the minimum number of swaps
        def process(x, y, m, n):
            L = [0] * m
            l = 0
            for i in range(n):
                while l < m and x[l] < y[i]:
                    l += 1
                if l < m:
                    L[l] = y[i]
                    l += 1
            return L

        ret = 0
        for i in range(n):
            v = process(x, y, m, n)
            ctr = 0
            while ctr < n and v[ctr] != w[i]:
                ctr += 1
            if ctr < n:
                for j in range(ctr, m):
                    x[j] = x[j + 1]
                x[m - 1] = w[i]
                ret += 1
        return ret
```

