def is_polite(n):
    # Start from the first polite number, which is 1
    polite_number = 1

    # Increment the number until we find the nth polite number
    while polite_number <= n:
        # Check if the current number is polite
        # A number is polite if it has an odd number of divisors
        count = 0
        for i in range(1, int(polite_number**0.5) + 1):
            if polite_number % i == 0:
                count += 1
                # If divisors are equal, it's a square number
                if i != polite_number // i:
                    count += 1
        # If it has an odd number of divisors, it's polite
        if count % 2 != 0:
            polite_number += 1
        else:
            # If it's not polite, the next number is
            polite_number += 1

    return polite_number
```

