def count_duplic(nums):
    # Initialize an empty dictionary to store the number and its frequency
    num_dic = {}
    # Lists to store ultimate result and final frequency
    result = []
    temp_f = []
    # Iterate through the list to find duplicate elements
    for i in range(len(nums)):
        # If the number is already in the dictionary, increment its frequency
        if nums[i] in num_dic:
            num_dic[nums[i]] += 1
            # If the frequency exceeds 1, add the number and its frequency to the temporary frequency list
            if num_dic[nums[i]] > 1:
                temp_f.append([nums[i], num_dic[nums[i]]])
        else:
            # If the number is not in the dictionary, add it along with a frequency of 1
            num_dic[nums[i]] = 1
            # If this is the first occurrence of the number, add it to the result list
            if i == 0 or i-1 != nums[i-1]:
                result.append(nums[i])
    # Return the ultimate result and the final frequency
    return (result, temp_f)
```

