def max_sum_of_three_consecutive(a, n):
    MA, MB, MC = a[0], 0, 0
    for i in range(2, n):
        MB, MC = MA, MA + a[i] + a[i-1]
        MA = max(MA + a[i], MB, MC)
    return max(MA, MB, MC)
