def max_sum_of_three_consecutive(arr, n):
    if n < 3:
        return 0
    dp = [0] * n
    dp[0], dp[1] = arr[0], arr[0] + arr[1]
    # Fill the dp array
    for i in range(2, n):
        dp[i] = max(arr[i] + dp[i - 3], dp[i - 1])
    return max(dp)
