def sub_lists(my_list):
    # Helper function to get all combinations of the list
    def get_combinations(lst, n):
        if n == 0:
            return [[]]
        elif n == len(lst):
            return [lst]
        combinations = []
        for i in range(len(lst)):
            current_element = lst[i]
            remaining_elements = lst[i+1:]
            for combination in get_combinations(remaining_elements, n-1):
                combinations.append([current_element]+combination)
        return combinations

    # Generating all sublists
    result = []
    for length in range(len(my_list)+1):
        comb = get_combinations(my_list, length)
        result.extend(comb)
    return result
