    dp = [[float('inf')] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = cost[0][0]  # Base case: cost at (0, 0)

    # Fill the DP array
    for i in range(m + 1):
        for j in range(n + 1):
            if i > 0:
                dp[i][j] = min(dp[i][j], dp[i - 1][j] + cost[i][j])
            if j > 0:
                dp[i][j] = min(dp[i][j], dp[i][j - 1] + cost[i][j])

    # The minimum cost path to reach (m, n) will be in dp[m][n]
    return dp[m][n]
