def min_Swaps(s1, s2):
    if len(s1) != len(s2):
        return -1  # If lengths are different, no swaps are needed
    mismatch_positions = []
    for i in range(len(s1)):
        if s1[i] != s2[i]:
            mismatch_positions.append(i)
    if len(mismatch_positions) % 2 != 0:
        return -1  # If number of mismatches is odd, impossible to convert
    min_swaps = 0
    swaps_made = set()
    for i in range(len(mismatch_positions)):
        k = i
        while k not in swaps_made:
            swaps_made.add(k)
            k = mismatch_positions[k]
            min_swaps += 1
    return min_swaps
```

