        return "Lengths of binary strings must be the same"
    swaps = 0
    for i in range(len_bin_str1):
        # If bits at i are not the same, swap them
        if bin_str1[i] != bin_str2[i]:
            # Find the first occurrence of the corresponding bit in bin_str2 starting from i+1
            for j in range(i+1, len_bin_str2):
                if bin_str2[j] == bin_str1[i]:
