def super_seq(s1, s2, m, n):
    # Create a 2D table to store lengths of the longest common subsequences
    dp_table = dp.create_2d DP_table(m+1, n+1)

    # Fill the dp_table in Bottom-Up manner
    for i in range(1, m+1):
        for j in range(1, n+1):
            if s1[i-1] == s2[j-1]:
                dp_table[i][j] = dp_table[i-1][j-1] + 1
            else:
                dp_table[i][j] = max(dp_table[i][j-1], dp_table[i-1][j])

    # The value in dp_table[m][n] will be the length of supersequence
    return dp_table[m][n]
