            if i == 0 or j == 0:
                dp_table[i][j] = 0
            elif str1[i - 1] == str2[j - 1]:
                dp_table[i][j] = dp_table[i - 1][j - 1] + 1
                longest_common_subseq = max(longest_common_subseq, dp_table[i][j])
            else:
                dp_table[i][j] = max(dp_table[i][j - 1], dp_table[i - 1][j])

    # The length of the supersequence
    return m + n - longest_common_subseq
