def isSubset(arr, size):
    # Traverse through all powerset of size \'size\'
    for sub in range(1, 1<<size): 
        temp = []
        # Copy elements of array to temp array
        # to store current combination
        for j in range(size): 
            if (sub & (1<<j)): 
                temp.append(arr[j]) 
        # If \'temp\' is the subset, increment count
        if (len(temp) == size) and (sub != 0): 
            return True
    return False
