import math

def lobb_num(a, b): 
    # A function to calculate the Lobb number for given a and b 
    if a < 1 or b < 1 or a > 200 or b > 200 or a == b: 
        return "Choose numbers between 1 and 200 and ensure a is not equal to b. "

    # A helper function to calculate factorial first 
    def factorial(n): 
        res = 1
        for i in range(1, n+1): 
            res = res * i 
        return res 

    # Calculate Lobb number using the formula ((b - a)! / (a! * (b + a - 2)!)) 
    if a == 1: 
        return factorial(b) 

    lobb_num = factorial(b) / (factorial(a) * factorial(b + a - 2)) 
    return int(round(lobb_num))
