  if low > high:
    return -1

  # Calculate the middle index
  mid = (low + high) // 2

  # If the middle element is the target, return the middle index
  if arr[mid] == target:
    if mid == high or arr[mid+1] != target:
      return mid
    else: # If the element is not at the end, move to the right
      return last(arr, target, mid+1, high)

  # If the middle element is less than the target, search in the right side
  elif arr[mid] < target:
    return last(arr, target, mid+1, high)

  # If the middle element is greater than the target, search in the left side
  else:
    return last(arr, target, low, mid-1)
