def find_Min_Swaps(arr, n):
    count = 0  # Initialize the count of swaps
    for i in range(n-1):
        # Find the index of the smallest element in the remaining unsorted portion
        min_index = i
        for j in range(i+1, n):
            if arr[min_index] > arr[j]:
                min_index = j
        # If the current element is not the smallest, perform a swap
        if arr[i] != arr[min_index]:
            arr[i], arr[min_index] = arr[min_index], arr[i]
            count += 1
    return count  # Return the total count of swaps
