import math

def sum_of_square(n):
    # Base case: sum of squares of binomial co-efficients for n=0 and n=1 is 1
    if n == 0 or n == 1:
        return 1
    # Using the formula (2n)! / ((n+1)! * n!)
    return math.factorial(2*n) // (math.factorial(n+1) * math.factorial(n))
