        s += ((-1)**i) * (binomial_coefficient(n, i) ** 2)  # Add to sum the square of binomial coefficient
    return s

def binomial_coefficient(n, m):  # Helper function to calculate binomial coefficient
    if m == 0 or m == n:
        return 1
    else:
        return binomial_coefficient(n-1, m-1) + binomial_coefficient(n-1, m)
