def extract_elements(lst, num):
    # Extract elements following each other continuously for 'num' occurrences
    result = []
    for i in range(len(lst) - num + 1):
        # Check if the current consecutive sequence is of length 'num'
        if len(set(lst[i:i+num])) == num:
            result.extend(lst[i:i+num])
    return result
